target.css:
:root {
  --ink: #1f2937;
  --muted: #6b7280;
  --surface: #ffffff;
  --line: #dbe3ee;
  --blue: #2563eb;
  --blue-soft: #eff6ff;
}

.sprint-card {
  width: 390px;
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.sprint-card h2 {
  margin: 0 0 3px;
  color: var(--ink);
  font-size: 18px;
  line-height: 1.2;
}

.task,
.timer p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.badge {
  padding: 4px 7px;
  color: var(--blue);
  background: var(--blue-soft);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.timer {
  margin: 16px 0;
  padding: 12px;
  text-align: center;
  background: var(--blue-soft);
  border-radius: 10px;
}

.time {
  display: block;
  color: var(--ink);
  font-size: 28px;
  line-height: 1;
}

.timer p {
  margin-top: 5px;
}

.controls {
  display: flex;
  gap: 8px;
}

button {
  flex: 1;
  padding: 9px 12px;
  color: var(--surface);
  background: var(--blue);
  border: 1px solid var(--blue);
  border-radius: 8px;
  font-size: 14px;
  font-weight: 700;
}

button.secondary {
  color: var(--ink);
  background: var(--surface);
  border-color: var(--line);
}
